window.__finlexDocLoaded(10216,{"id":10216,"articles":[{"id":1000910,"no":"Overview","heading":"Scope & Core Objective (Public Summary)","text":"Establishes accounting for defined benefit pension plans (ASC 715-30), other postretirement benefits (ASC 715-60), and defined contribution plans (ASC 715-70).","seq":0},{"id":1000911,"no":"ASC 715-30","heading":"Corridor Amortization, Expected Return & Prior Service Cost","text":"• Net Periodic Benefit Cost: Service cost is presented with other compensation costs; non-service components (interest cost, expected return on plan assets, amortizations) are presented outside operating income (ASU 2017-07).\n• Actuarial Gains/Losses & Prior Service Cost: Initially recorded in OCI and subsequently AMORTIZED (recycled) into net income (corridor approach or systematic method).\n• Expected Return on Plan Assets: Uses expected long-term rate of return on plan assets (not the discount rate).","seq":1},{"id":1000912,"no":"US GAAP vs. IFRS / CAS","heading":"Key Cross-Framework Differences","text":"• Major Divergence from IAS 19 / CAS 9: IAS 19 calculates a single 'net interest' using the discount rate, recognizes past service cost IMMEDIATELY in P&L, and NEVER recycles OCI remeasurements to P&L; ASC 715 uses expected return on plan assets and recycles actuarial gains/losses and prior service cost from AOCI into P&L.","seq":2},{"id":1000913,"no":"Official Access","heading":"Official FASB Codification & Reference Entry","text":"Official Portal (FASB Accounting Standards Codification®): https://asc.fasb.org/\nStatus: in_force (FASB ASC free Basic View available at https://asc.fasb.org/).","seq":3}]});
